interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: string, fallback?: string) => string;
}

const LanguageContext = createContext<LanguageContextType>({
  language: "en",
  setLanguage: () => {},
  t: (key: string, fallback?: string) => fallback || key,
});

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem("agritwin_lang") as Language;
      if (saved && ["en", "kn", "hi", "ta", "te", "ml", "mr", "bn", "pa"].includes(saved)) {
        return saved;
      }
    }
    return "en";
  });

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    if (typeof window !== "undefined") {
      localStorage.setItem("agritwin_lang", lang);
      // Synchronize with voice assistant preference
      localStorage.setItem("agritwin_voice_lang", lang);
    }
  };

  const t = (key: string, fallback?: string): string => {
    // 1. Direct key match in TRANSLATIONS
    const langDict = TRANSLATIONS[language] || TRANSLATIONS.en;
    if (langDict && langDict[key]) {
      return langDict[key];
    }
    // 2. Direct phrase match in PHRASE_TRANSLATIONS
    const phraseDict = PHRASE_TRANSLATIONS[language];
    if (phraseDict && phraseDict[key]) {
      return phraseDict[key];
    }
    // 3. Fallback to English TRANSLATIONS
    if (TRANSLATIONS.en && TRANSLATIONS.en[key]) {
      return TRANSLATIONS.en[key];
    }
    // 4. Fallback phrase in PHRASE_TRANSLATIONS
    if (fallback && phraseDict && phraseDict[fallback]) {
      return phraseDict[fallback];
    }
    return fallback || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useTranslation() {
  return useContext(LanguageContext);
}

export function translateCrop(cropName: string, lang: Language): string {
  const normalized = (cropName || "").toLowerCase();
  if (normalized.includes("potato")) {
    return lang === "kn" ? "ಆಲೂಗಡ್ಡೆ" : lang === "hi" ? "आलू" : lang === "ta" ? "உருளைக்கிழங்கு" : lang === "te" ? "బంగాళాదుంప" : lang === "ml" ? "ഉരുളക്കിഴങ്ങ്" : lang === "mr" ? "बटाटा" : lang === "bn" ? "আলু" : lang === "pa" ? "ਆਲੂ" : "Potato";
  }
  if (normalized.includes("onion")) {
    return lang === "kn" ? "ಈರುಳ್ಳಿ" : lang === "hi" ? "प्याज" : lang === "ta" ? "வெங்காயம்" : lang === "te" ? "ఉల్లిపాయ" : lang === "ml" ? "സവാള / ഉള്ളി" : lang === "mr" ? "कांदा" : lang === "bn" ? "পেঁয়াজ" : lang === "pa" ? "ਪਿਆਜ਼" : "Onion";
  }
  if (normalized.includes("carrot")) {
    return lang === "kn" ? "ಕ್ಯಾರೆಟ್" : lang === "hi" ? "गाजर" : lang === "ta" ? "கேரட்" : lang === "te" ? "క్యారెట్" : lang === "ml" ? "കാരറ്റ്" : lang === "mr" ? "गाजर" : lang === "bn" ? "গাজর" : lang === "pa" ? "ਗਾਜਰ" : "Carrot";
  }
  if (normalized.includes("beetroot")) {
    return lang === "kn" ? "ಬೀಟ್‌ರೂಟ್" : lang === "hi" ? "चुकंदर" : lang === "ta" ? "பீட்ரூட்" : lang === "te" ? "బీట్‌రూట్" : lang === "ml" ? "ബീറ്റ്‌റൂട്ട്" : lang === "mr" ? "बीट" : lang === "bn" ? "বিট" : lang === "pa" ? "ਚਕੰਦਰ" : "Beetroot";
  }
  if (normalized.includes("ragi") || normalized.includes("millet")) {
    return lang === "kn" ? "ರಾಗಿ (ಬೆರಳು ರಾಗಿ)" : lang === "hi" ? "रागी (मंडुआ)" : lang === "ta" ? "கேழ்வரகு" : lang === "te" ? "రాగులు" : lang === "ml" ? "കൂവരക്" : lang === "mr" ? "नाचणी" : lang === "bn" ? "মারুয়া / রাগি" : lang === "pa" ? "ਕੋਧਰਾ" : "Ragi (Finger Millet)";
  }
  if (normalized.includes("tomato")) {
    return lang === "kn" ? "ಟೊಮೆಟೊ" : lang === "hi" ? "टमाटर" : lang === "ta" ? "தக்காளி" : lang === "te" ? "టమోటా" : lang === "ml" ? "തക്കാളി" : lang === "mr" ? "टोमॅटो" : lang === "bn" ? "টমেটো" : lang === "pa" ? "ਟਮਾਟਰ" : "Tomato";
  }
  if (normalized.includes("sugarcane") || normalized.includes("cane")) {
    return lang === "kn" ? "ಕಬ್ಬು" : lang === "hi" ? "गन्ना" : lang === "ta" ? "கரும்பு" : lang === "te" ? "చెరకు" : lang === "ml" ? "കരിമ്പ്" : lang === "mr" ? "ऊस" : lang === "bn" ? "আখ" : lang === "pa" ? "ਗੰਨਾ" : "Sugarcane";
  }
  if (normalized.includes("groundnut") || normalized.includes("peanut")) {
    return lang === "kn" ? "ಕಡಲೆಕಾಯಿ / ಶೇಂಗಾ" : lang === "hi" ? "मूंगफली" : lang === "ta" ? "நிலக்கடலை" : lang === "te" ? "వేరుశెనగ" : lang === "ml" ? "നിലക്കടല" : lang === "mr" ? "भुईमूग / शेंगदाणा" : lang === "bn" ? "চীনাবাদাম" : lang === "pa" ? "ਮੂੰਗਫਲੀ" : "Groundnut / Peanut";
  }
  if (normalized.includes("rice") || normalized.includes("paddy")) {
    return lang === "kn" ? "ಭತ್ತ / ಅಕ್ಕಿ" : lang === "hi" ? "धान / चावल" : lang === "ta" ? "நெல் / அரிசி" : lang === "te" ? "వరి / బియ్యం" : lang === "ml" ? "നെല്ല് / അരി" : lang === "mr" ? "भात / तांदूळ" : lang === "bn" ? "ধান / চাল" : lang === "pa" ? "ਚਾਵਲ / ਝੋਨਾ" : "Rice / Paddy";
  }
  if (normalized.includes("wheat")) {
    return lang === "kn" ? "ಗೋಧಿ" : lang === "hi" ? "गेहूं" : lang === "ta" ? "கோதுமை" : lang === "te" ? "గోధుమలు" : lang === "ml" ? "ഗോതമ്പ്" : lang === "mr" ? "गहू" : lang === "bn" ? "গম" : lang === "pa" ? "ਕਣਕ" : "Wheat";
  }
  if (normalized.includes("maize") || normalized.includes("corn")) {
    return lang === "kn" ? "ಮೆಕ್ಕೆಜೋಳ" : lang === "hi" ? "मक्का" : lang === "ta" ? "மக்காச்சோளம்" : lang === "te" ? "మొక్కజొన్న" : lang === "ml" ? "ചോളം" : lang === "mr" ? "मका" : lang === "bn" ? "ভুট্টা" : lang === "pa" ? "ਮੱਕੀ" : "Maize / Corn";
  }
  if (normalized.includes("cotton")) {
    return lang === "kn" ? "ಹತ್ತಿ" : lang === "hi" ? "कपास" : lang === "ta" ? "பருத்தி" : lang === "te" ? "పత్తి" : lang === "ml" ? "പരുത്തി" : lang === "mr" ? "कापूस" : lang === "bn" ? "তুলা" : lang === "pa" ? "ਕਪਾਹ" : "Cotton";
  }
  if (normalized.includes("banana")) {
    return lang === "kn" ? "ಬಾಳೆ" : lang === "hi" ? "केला" : lang === "ta" ? "வாழை" : lang === "te" ? "అరటి" : lang === "ml" ? "വാഴ" : lang === "mr" ? "केळी" : lang === "bn" ? "কলা" : lang === "pa" ? "ਕੇਲਾ" : "Banana";
  }
  return cropName;
}

export function translateGrowthStage(stage: string, lang: Language): string {
  const s = (stage || "").toLowerCase();
  if (s.includes("tuber initiation") || s.includes("bulking") || s.includes("tuber bulking")) {
    return lang === "kn" ? "ಗಡ್ಡೆ ಕಟ್ಟುವ ಮತ್ತು ಬೆಳೆಯುವ ಹಂತ" : lang === "hi" ? "कंद निर्माण और विकास अवस्था" : lang === "ta" ? "கிழங்கு உருவாக்கம் நிலை" : lang === "te" ? "దుంప ఊరే దశ" : lang === "ml" ? "കിഴങ്ങ് ഉണ്ടാകുന്ന ഘട്ടം" : lang === "mr" ? "कंद पोसणे अवस्था" : lang === "bn" ? "কন্দ বৃদ্ধির পর্যায়" : lang === "pa" ? "ਆਲੂ ਬਣਨ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("bulb development") || s.includes("bulbing")) {
    return lang === "kn" ? "ಗೆಡ್ಡೆ ಕಟ್ಟುವ ಹಂತ" : lang === "hi" ? "कंद/गांठ बनने की अवस्था" : lang === "ta" ? "வெங்காய உருவாக்கம் நிலை" : lang === "te" ? "ఉల్లిపాయ ఊరే దశ" : lang === "ml" ? "ഉള്ളി വലുതാകുന്ന ഘട്ടം" : lang === "mr" ? "कांदा फुगवण अवस्था" : lang === "bn" ? "পেঁয়াজ বৃদ্ধির পর্যায়" : lang === "pa" ? "ਗੰਢਾ ਬਣਨ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("root development") || s.includes("root enlargement")) {
    return lang === "kn" ? "ಬೇರು ಕ್ಯಾರೆಟ್ ಬೆಳೆಯುವ ಹಂತ" : lang === "hi" ? "जड़ विस्तार अवस्था" : lang === "ta" ? "வேர் வளர்ச்சி நிலை" : lang === "te" ? "వేరు వృద్ధి దశ" : lang === "ml" ? "വേര് വളരുന്ന ഘട്ടം" : lang === "mr" ? "मुळे वाढीचा काळ" : lang === "bn" ? "মূল বৃদ্ধির পর্যায়" : lang === "pa" ? "ਜੜ੍ਹ ਵਧਣ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("grain fill") || s.includes("milking")) {
    return lang === "kn" ? "ಕಾಳು ತುಂಬುವ ಹಂತ" : lang === "hi" ? "दाना भरने की अवस्था" : lang === "ta" ? "தானியம் நிரப்பும் நிலை" : lang === "te" ? "గింజ నిండే దశ" : lang === "ml" ? "മണി നിറയുന്ന ഘട്ടം" : lang === "mr" ? "दाणे भरणे टप्पा" : lang === "bn" ? "দানা ভরার পর্যায়" : lang === "pa" ? "ਦਾਣੇ ਭਰਨ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("fruiting") || s.includes("ripening")) {
    return lang === "kn" ? "ಕಾಯಿ ಮತ್ತು ಹಣ್ಣಾಗುವ ಹಂತ" : lang === "hi" ? "फलने और पकने की अवस्था" : lang === "ta" ? "காய்க்கும் மற்றும் பழுக்கும் நிலை" : lang === "te" ? "కాయలు కాసే & పక్వ దశ" : lang === "ml" ? "ഫലം വിളയുന്ന ഘട്ടം" : lang === "mr" ? "फळ धरणे व पिकणे" : lang === "bn" ? "ফল ধরা ও পাকার পর্যায়" : lang === "pa" ? "ਫਲ ਲੱਗਣ ਅਤੇ ਪੱਕਣ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("grand growth")) {
    return lang === "kn" ? "ತೀವ್ರ ಕಬ್ಬಿನ ಬೆಳವಣಿಗೆ ಹಂತ" : lang === "hi" ? "मुख्य विकास अवस्था" : lang === "ta" ? "தீவிர வளர்ச்சி நிலை" : lang === "te" ? "ప్రధాన పెరుగుదల దశ" : lang === "ml" ? "ദ്രുത വളർച്ചാ ഘട്ടം" : lang === "mr" ? "मुख्य वाढीचा काळ" : lang === "bn" ? "মূল বৃদ্ধি পর্যায়" : lang === "pa" ? "ਮੁੱਖ ਵਾਧੇ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("pegging") || s.includes("pod")) {
    return lang === "kn" ? "ಊಡು ಬಿಡುವ ಮತ್ತು ಕಾಯಿ ಕಟ್ಟುವ ಹಂತ" : lang === "hi" ? "पेगिंग और फली बनने की अवस्था" : lang === "ta" ? "விழுது பாய்தல் நிலை" : lang === "te" ? "ఊడలు దిగే దశ" : lang === "ml" ? "കായ് പിടിക്കുന്ന ഘട്ടം" : lang === "mr" ? "आरे फुटणे व शेंग भरणे" : lang === "bn" ? "শুঁটি গঠনের পর্যায়" : lang === "pa" ? "ਫਲੀ ਬਣਨ ਦਾ ਪੜਾਅ" : stage;
  }
  if (s.includes("vegetative") || s.includes("tillering")) {
    return lang === "kn" ? "ಸಸ್ಯಕ ಬೆಳವಣಿಗೆ ಹಂತ" : lang === "hi" ? "वानस्पतिक विकास अवस्था" : lang === "ta" ? "பயிர் வளர்ச்சி நிலை" : lang === "te" ? "శాకీయ పెరుగుదల దశ" : lang === "ml" ? "ശാഖാവളർച്ചാ ഘട്ടം" : lang === "mr" ? "शाकीय वाढीची अवस्था" : lang === "bn" ? "অঙ্গজ বৃদ্ধি পর্যায়" : lang === "pa" ? "ਵਨਸਪਤੀ ਵਾਧੇ ਦਾ ਪੜਾਅ" : stage;
  }
  return stage;
}

export function translateSoil(soilType: string, lang: Language): string {
  const s = (soilType || "").toLowerCase();
  if (s.includes("red") && s.includes("sandy")) {
    return lang === "kn" ? "ಕೆಂಪು ಮರಳು ಮಿಶ್ರಿತ ಜೇಡಿಮಣ್ಣು" : lang === "hi" ? "लाल रेतीली दोमट मिट्टी" : lang === "ta" ? "செம்மண் மணல் கலவை" : lang === "te" ? "ఎర్ర ఇసుక నేల" : lang === "ml" ? "ചുവന്ന മണൽ കലർന്ന മണ്ണ്" : lang === "mr" ? "तांबडी वालुकामय जमीन" : lang === "bn" ? "লাল বেলে দোআঁশ মাটি" : lang === "pa" ? "ਲਾਲ ਰੇਤਲੀ ਜ਼ਮੀਨ" : "Red Sandy Loam";
  }
  if (s.includes("clay")) {
    return lang === "kn" ? "ಆಳವಾದ ಕೆಂಪು ಜೇಡಿ ಮಣ್ಣು" : lang === "hi" ? "गहरी लाल चिकनी मिट्टी" : lang === "ta" ? "ஆழ்ந்த செம்மண் களிமண்" : lang === "te" ? "లోతైన ఎర్ర బంకమట్టి" : lang === "ml" ? "ചുവന്ന എക്കൽ മണ്ണ്" : lang === "mr" ? "काळी चिकनमाती" : lang === "bn" ? "লাল এঁটেল মাটি" : lang === "pa" ? "ਚੀਕਣੀ ਮਿੱਟੀ" : "Deep Red Clay Loam";
  }
  if (s.includes("alluvial")) {
    return lang === "kn" ? "ಆಳವಾದ ಮೆಕ್ಕಲು ಮಣ್ಣು" : lang === "hi" ? "गहरी जलोढ़ दोमट मिट्टी" : lang === "ta" ? "ஆழ்ந்த வண்டல் மண்" : lang === "te" ? "లోతైన ఒండ్రు నేల" : lang === "ml" ? "എക്കൽ മണ്ണ്" : lang === "mr" ? "गाळाची जमीन" : lang === "bn" ? "পলি মাটি" : lang === "pa" ? "ਜਲੋੜ੍ਹ ਮਿੱਟੀ" : "Deep Alluvial Loam";
  }
  return soilType;
}
